import type { ReactNode } from 'react';
import { Brand, Icon } from './ui';
const navigation=[['Projects','/projects/'],['Documentation','/docs/'],['Trust','/trust/'],['About','/about/']];
function NavLinks({path}:{path:string}){return <>{navigation.map(([label,href])=><a key={href} href={href} aria-current={path.startsWith(href)?'page':undefined}>{label}</a>)}</>}
export function Shell({path,children}:{path:string;children:ReactNode}){
 return <div className="site" data-route={path}>
  <a className="skip-link" href="#main">Skip to content</a>
  <header className="site-header"><div className="header-inner"><Brand/><nav className="desktop-nav" aria-label="Main"><NavLinks path={path}/></nav><div className="header-tools"><button className="icon-button search-trigger" type="button" data-open-search="" aria-label="Search documentation"><Icon name="search"/></button><button className="icon-button" type="button" data-theme-toggle="" aria-label="Switch color theme" title="Switch color theme"><Icon name="sun"/></button><a className="header-source" href="https://github.com/donaldfilimon/MLAI-CORPORATION-WWW" target="_blank" rel="noopener noreferrer">View source<Icon name="external"/></a><button className="icon-button mobile-trigger" data-open-menu="" type="button" aria-label="Open navigation" aria-haspopup="dialog" aria-expanded="false" aria-controls="mobile-menu"><Icon name="menu"/></button></div></div></header>
  <main id="main" tabIndex={-1}>{children}</main>
  <footer className="site-footer"><div className="container footer-top"><div><Brand/><p>Software worth understanding.</p></div><nav aria-label="Footer"><NavLinks path={path}/><a href="/brief/">Project brief</a></nav><a className="footer-source" href="https://github.com/donaldfilimon" target="_blank" rel="noopener noreferrer">Donald Filimon<Icon name="external"/></a></div><div className="container footer-bottom"><span>Independent review preview · Not the production site</span><span>Source review · 07 Sep 2026</span></div></footer>
  <dialog id="search-dialog" className="search-dialog" aria-labelledby="search-title"><div className="search-heading"><h2 id="search-title">Find your next step.</h2><button className="icon-button" type="button" data-close-search="" aria-label="Close search"><Icon name="close"/></button></div><div className="search-field"><Icon name="search"/><input id="docs-search" type="search" placeholder="Search guides, projects, and concepts…" aria-label="Search documentation" role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls="search-results" autoComplete="off" maxLength={200}/><kbd>esc</kbd></div><p id="search-count" className="search-count" aria-live="polite"></p><div id="search-results" role="listbox" aria-label="Search results"></div><div className="search-footer"><span>↑ ↓ to navigate · Enter to open</span><span>Local search. No queries sent.</span></div></dialog>
  <dialog id="mobile-menu" className="mobile-dialog" aria-label="Navigation"><div className="mobile-menu-head"><Brand/><button className="icon-button" data-close-menu="" type="button" aria-label="Close navigation"><Icon name="close"/></button></div><nav aria-label="Mobile"><NavLinks path={path}/><a href="/brief/">Start a project brief</a></nav><p>Explore the work. Inspect the source.</p></dialog>
  <div id="site-status" className="sr-only" role="status"></div>
 </div>;
}
